/**
 * 内部の選択肢キー。IPA等は先頭4〜5個だけを使う。電験二種一次試験は公式の
 * 解答群(イ)〜(ヨ)の15肢を、順番どおり ア〜ソ に割り当てて保持する。
 */
export type ChoiceKey = "ア" | "イ" | "ウ" | "エ" | "オ" | "カ" | "キ" | "ク" | "ケ" | "コ" | "サ" | "シ" | "ス" | "セ" | "ソ" | "タ" | "チ" | "ツ" | "テ" | "ト"
